import { ObjectUtils_isEqual } from "../../utils/object";
import {
  IVersionTypes,
  ITypedObject,
  IFieldVersion,
  IVectorClock,
  IIdVersion,
  IVersionsObject,
  IVersionValue,
  IVersions,
  ICollectionVersions,
  isVectorClock,
  isIdVersion,
  isCollectionVersions,
  isVersionsObject,
} from "./types";

export function VersionTrackerUtils_isAtomicType<TAtomicType extends string, TControlledType extends string>(
  value: unknown,
  versionTypes: IVersionTypes<TAtomicType, TControlledType>
): value is ITypedObject<TAtomicType> {
  return VersionTrackerUtils_isTypedObject(value) && versionTypes.atomicTypes.includes(value.vtype as TAtomicType);
}

export function VersionTrackerUtils_isControlledType<TAtomicType extends string, TControlledType extends string>(
  value: unknown,
  versionTypes: IVersionTypes<TAtomicType, TControlledType>
): value is ITypedObject<TControlledType> {
  return (
    VersionTrackerUtils_isTypedObject(value) && versionTypes.controlledTypes.includes(value.vtype as TControlledType)
  );
}

export function VersionTrackerUtils_isTypedObject(value: unknown): value is ITypedObject {
  return typeof value === "object" && value !== null && "vtype" in value && typeof value.vtype === "string";
}

export function VersionTrackerUtils_isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

export function VersionTrackerUtils_areEqual(a: unknown, b: unknown): boolean {
  return ObjectUtils_isEqual(a as Record<string, unknown>, b as Record<string, unknown>);
}

export function VersionTrackerUtils_getId<TAtomicType extends string, TControlledType extends string>(
  obj: unknown,
  versionTypes: IVersionTypes<TAtomicType, TControlledType>
): string | undefined {
  if (!VersionTrackerUtils_isTypedObject(obj)) {
    return undefined;
  }
  const idField = versionTypes.typeIdMapping[obj.vtype as TAtomicType | TControlledType];
  if (!idField || !(idField in obj)) {
    return undefined;
  }
  const id = obj[idField];
  return id != null ? String(id) : undefined;
}

export function VersionTrackerUtils_asVersionsObject<T>(versions: IVersions<T>): IVersionsObject {
  return versions as IVersionsObject;
}

export function VersionTrackerUtils_ensureVersionsObject(version: IVersionValue | undefined): IVersionsObject {
  if (isVersionsObject(version)) {
    return version;
  }
  return {};
}

export function VersionTrackerUtils_ensureCollectionVersions(version: IVersionValue | undefined): ICollectionVersions {
  if (isCollectionVersions(version)) {
    return version;
  }
  return { items: {}, deleted: {} };
}

export function VersionTrackerUtils_createVersion(
  timestamp: number,
  currentVersion: IFieldVersion | undefined,
  deviceId?: string
): IFieldVersion {
  if (!deviceId) {
    return timestamp;
  }

  const current = VersionTrackerUtils_normalizeVersion(currentVersion);
  const newClock = { ...current.vc };
  newClock[deviceId] = (newClock[deviceId] || 0) + 1;

  return {
    vc: newClock,
    t: timestamp,
  };
}

export function VersionTrackerUtils_normalizeVersion(version?: IFieldVersion): IVectorClock {
  if (!version) {
    return { vc: {}, t: 0 };
  }
  if (isVectorClock(version)) {
    return version;
  }
  return { vc: {}, t: version };
}

export function VersionTrackerUtils_compareVersions(
  a: IFieldVersion,
  b: IFieldVersion
): "a_newer" | "b_newer" | "concurrent" | "equal" {
  const aNorm = VersionTrackerUtils_normalizeVersion(a);
  const bNorm = VersionTrackerUtils_normalizeVersion(b);

  const aDevices = Object.keys(aNorm.vc);
  const bDevices = Object.keys(bNorm.vc);
  const aHasVc = aDevices.length > 0;
  const bHasVc = bDevices.length > 0;

  if (aHasVc !== bHasVc) {
    if (aNorm.t === bNorm.t) {
      return "equal";
    }
    return aNorm.t > bNorm.t ? "a_newer" : "b_newer";
  }

  if (!aHasVc && !bHasVc) {
    if (aNorm.t === bNorm.t) {
      return "equal";
    }
    return aNorm.t > bNorm.t ? "a_newer" : "b_newer";
  }

  const allDevices = new Set([...aDevices, ...bDevices]);
  let aHasHigher = false;
  let bHasHigher = false;

  for (const deviceId of allDevices) {
    const aCount = aNorm.vc[deviceId] || 0;
    const bCount = bNorm.vc[deviceId] || 0;

    if (aCount > bCount) {
      aHasHigher = true;
    }
    if (bCount > aCount) {
      bHasHigher = true;
    }
  }

  if (!aHasHigher && !bHasHigher) {
    return "equal";
  }
  if (aHasHigher && !bHasHigher) {
    return "a_newer";
  }
  if (bHasHigher && !aHasHigher) {
    return "b_newer";
  }
  return "concurrent";
}

export function VersionTrackerUtils_mergeFieldVersions(a: IFieldVersion, b: IFieldVersion): IFieldVersion {
  const comparison = VersionTrackerUtils_compareVersions(a, b);
  if (comparison === "a_newer") {
    return a;
  }
  if (comparison === "b_newer") {
    return b;
  }
  if (comparison === "equal") {
    return a;
  }

  const aNorm = VersionTrackerUtils_normalizeVersion(a);
  const bNorm = VersionTrackerUtils_normalizeVersion(b);

  const allDevices = new Set([...Object.keys(aNorm.vc), ...Object.keys(bNorm.vc)]);
  const mergedVc: { [deviceId: string]: number } = {};

  for (const deviceId of allDevices) {
    mergedVc[deviceId] = Math.max(aNorm.vc[deviceId] || 0, bNorm.vc[deviceId] || 0);
  }

  return {
    vc: mergedVc,
    t: Math.max(aNorm.t, bNorm.t),
  };
}

export function VersionTrackerUtils_incrementNukedeleted(collection: ICollectionVersions): ICollectionVersions {
  if (collection.nukedeleted == null) {
    return collection;
  }
  const next = collection.nukedeleted + 1;
  if (next > VersionTrackerUtils_NUKEDELETED_THRESHOLD) {
    const { nukedeleted, ...rest } = collection;
    return rest;
  }
  return { ...collection, nukedeleted: next };
}

export function VersionTrackerUtils_applyCompaction<TAtomicType extends string, TControlledType extends string>(
  collection: ICollectionVersions,
  path: string,
  currentTimestamp: number,
  versionTypes: IVersionTypes<TAtomicType, TControlledType>
): ICollectionVersions {
  const threshold = path && versionTypes.compactionThresholds ? versionTypes.compactionThresholds[path] : undefined;

  if (!threshold || !collection.deleted || Object.keys(collection.deleted).length === 0) {
    return collection;
  }

  const result: ICollectionVersions = {
    items: collection.items,
    deleted: {},
  };

  for (const [key, deletionTimestamp] of Object.entries(collection.deleted)) {
    if (currentTimestamp - deletionTimestamp < threshold) {
      result.deleted![key] = deletionTimestamp;
    }
  }

  return result;
}

export function VersionTrackerUtils_getIdFieldName<TAtomicType extends string, TControlledType extends string>(
  vtype: TControlledType,
  versionTypes: IVersionTypes<TAtomicType, TControlledType>
): string | undefined {
  return versionTypes.typeIdMapping[vtype];
}

export function VersionTrackerUtils_createIdVersion(
  timestamp: number,
  value: string,
  currentVersion: IIdVersion | undefined,
  deviceId?: string
): IIdVersion {
  if (!deviceId) {
    return {
      vc: currentVersion?.vc || {},
      t: timestamp,
      value,
    };
  }

  const current = currentVersion ? { vc: currentVersion.vc, t: currentVersion.t } : { vc: {}, t: 0 };
  const newClock = { ...current.vc };
  newClock[deviceId] = (newClock[deviceId] || 0) + 1;

  return {
    vc: newClock,
    t: timestamp,
    value,
  };
}

export function VersionTrackerUtils_pickWinningIdVersion(a: IIdVersion, b: IIdVersion): IIdVersion {
  const comparison = VersionTrackerUtils_compareVersions(a, b);
  if (comparison === "a_newer") {
    return a;
  }
  if (comparison === "b_newer") {
    return b;
  }
  // For concurrent or equal, use timestamp as tiebreaker
  return a.t >= b.t ? a : b;
}

export function VersionTrackerUtils_getIdValue<TAtomicType extends string, TControlledType extends string>(
  obj: unknown,
  versionTypes: IVersionTypes<TAtomicType, TControlledType>
): string | undefined {
  if (!VersionTrackerUtils_isControlledType(obj, versionTypes)) {
    return undefined;
  }
  const idField = versionTypes.typeIdMapping[obj.vtype];
  if (!idField || !(idField in obj)) {
    return undefined;
  }
  const id = obj[idField];
  return id != null ? String(id) : undefined;
}

export function VersionTrackerUtils_getIdVersionFromVersions<
  TAtomicType extends string,
  TControlledType extends string,
>(
  vtype: TControlledType,
  versions: IVersionsObject | undefined,
  versionTypes: IVersionTypes<TAtomicType, TControlledType>
): IIdVersion | undefined {
  if (!versions) {
    return undefined;
  }
  const idField = versionTypes.typeIdMapping[vtype];
  if (!idField) {
    return undefined;
  }
  const idVersion = versions[idField];
  return isIdVersion(idVersion) ? idVersion : undefined;
}

export const VersionTrackerUtils_NUKEDELETED_THRESHOLD = 3;
